    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    # Eğer result uzunluğu all_packages'tan küçükse döngü vardır
    if len(result) < n:
        # Döngüyü bulmak için DFS kullanalım (req -> pkg yönünde değil, bağımlılık yönünde)
